describe('Mobile Navigation Hamburger Menu', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.viewport('iphone-x');
  });

  it('should display hamburger menu icon on mobile viewport', () => {
    cy.get('[data-testid="hamburger-menu"]').should('be.visible');
    cy.get('[data-testid="nav-menu"]').should('not.be.visible');
  });

  it('should toggle navigation menu when hamburger icon is clicked', () => {
    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="nav-menu"]').should('be.visible');
    cy.get('[data-testid="nav-menu"]').should('have.class', 'open');

    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="nav-menu"]').should('not.be.visible');
  });

  it('should close menu when a navigation link is clicked', () => {
    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="nav-menu"]').should('be.visible');

    cy.get('[data-testid="nav-link"]').first().click();
    cy.get('[data-testid="nav-menu"]').should('not.be.visible');
  });

  it('should close menu when clicking outside the menu', () => {
    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="nav-menu"]').should('be.visible');

    cy.get('body').click(0, 0);
    cy.get('[data-testid="nav-menu"]').should('not.be.visible');
  });

  it('should display hamburger menu on tablet in portrait mode', () => {
    cy.viewport('ipad-2');
    cy.get('[data-testid="hamburger-menu"]').should('be.visible');
  });

  it('should hide hamburger menu and show full navigation on desktop', () => {
    cy.viewport(1920, 1080);
    cy.get('[data-testid="hamburger-menu"]').should('not.be.visible');
    cy.get('[data-testid="nav-menu"]').should('be.visible');
    cy.get('[data-testid="nav-menu"]').should('not.have.class', 'open');
  });

  it('should maintain menu state during viewport resize', () => {
    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="nav-menu"]').should('be.visible');

    cy.viewport('iphone-se2');
    cy.get('[data-testid="nav-menu"]').should('be.visible');
  });

  it('should have proper accessibility attributes on hamburger menu', () => {
    cy.get('[data-testid="hamburger-menu"]')
      .should('have.attr', 'aria-label')
      .and('include', 'menu');

    cy.get('[data-testid="hamburger-menu"]')
      .should('have.attr', 'aria-expanded', 'false');

    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="hamburger-menu"]')
      .should('have.attr', 'aria-expanded', 'true');
  });

  it('should handle rapid menu toggle clicks', () => {
    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="hamburger-menu"]').click();
    cy.get('[data-testid="hamburger-menu"]').click();

    cy.get('[data-testid="nav-menu"]').should('be.visible');
  });

  it('should display all navigation items in mobile menu', () => {
    cy.get('[data-testid="hamburger-menu"]').click();

    cy.get('[data-testid="nav-menu"]').within(() => {
      cy.get('[data-testid="nav-link"]').should('have.length.greaterThan', 0);
      cy.get('[data-testid="nav-link"]').each(($link) => {
        cy.wrap($link).should('be.visible');
      });
    });
  });
});
